mapper.select:
SELECT /*+ LEADING(T1 S1) USE_NL(S1) INDEX(T1 idx_SMI1_1) */ S1.userid AS userid, S1.username AS username, S1.brth AS brth, S1.email AS email, S1.regdate AS regdate, S1.grade AS grade, T1.pfnum AS pfnum, T1.pcnum AS pcnum, T1.pbnum AS pbnum FROM SMI1 T1 INNER JOIN SM01 S1 ON T1.userid = S1.userid WHERE T1.pbnum = #{cellpbnum}
AND T1.pcnum = #{cellpcnum}
AND T1.pfnum = #{cellpfnum}
AND T1.infocode = 1 AND NOT EXISTS ( SELECT /*+ UNNEST NL_AJ */ 1 FROM SME1 E1 WHERE T1.userid = E1.userid )
